// PRIVATE authoring corpus. Never import into the browser or a public response.
// Original scenarios informed by sources-data.json; no company question claims.
// Grade anchors and rubrics are proposals, not empirically calibrated judgments.
const grades = ['Intern', 'Junior', 'Middle', 'Senior', 'Lead'];
const rows = [];
function F(specialization, group, slug, title, prompt, language, sources, criteria, levels, alternatives, errors) {
  const prefix = { ML: 'ml', DataAnalysis: 'analysis', DataEngineering: 'engineering' }[specialization];
  rows.push({
    id: `open-${prefix}-${slug}`, specialization, group, title, prompt,
    answerFormat: language ? 'code' : 'text', language,
    sourceIds: sources.map(id => 'data-' + id), tags: [slug, group.toLowerCase(), language || 'reasoning'],
    referenceAnswer: criteria.map(item => item[1]).join(' '),
    acceptableAlternatives: alternatives, criticalErrors: errors,
    criteria: criteria.map(([label, meets, strong], index) => ({
      id: 'criterion-' + (index + 1), label,
      missing: 'Не рассматривает: ' + label + '.',
      partial: 'Обозначает ' + label + ', но не обосновывает требуемое действие: ' + meets,
      meets, strong: meets + ' Дополнительно: ' + strong,
    })),
    levels: Object.fromEntries(grades.map((grade, index) => [grade, {
      task: (grade === 'Intern' ? 'Объём этого уровня ограничен следующим заданием: ' : '')
        + levels[index][0] + ' Выполните указанное действие или решите исходную задачу с этими условиями; обоснуйте ответ.'
        + (grade === 'Intern' ? ' Расширенный промышленный план для этого уровня не требуется.' : ''),
      expected: levels[index][1],
    }])),
    personalization: { allowed: ['domain', 'entityNames'], invariants: [
      'Сохранить числа, единицы, схему данных, доступность признаков и порядок событий.',
      'Не менять ограничения ресурсов, требуемые действия уровня, критерии и критические ошибки.',
      'Опыт кандидата задаёт названия и контекст, но не служит доказательством компетенции.',
    ] },
  });
}

